// Full-text search over titles, aliases, tags, excerpts and the indexed body of every artifact.
// The body comes from graph/search_index.js (window.TENIR_SEARCH_INDEX), generated by build_search_index.py.
// Matching is per word (prefix, accent- and case-insensitive): every word of the query must be found
// somewhere in the node; if nothing satisfies that, partial matches are returned and flagged.
var SearchIndexer = (function() {
  'use strict';
  let nodes = [], docs = null, lastHits = {}, lastInfo = { terms:[], partial:false, indexed:0 };
  const STOP = new Set(('a an and are as at be by for from in is it of on or that the this to with ' +
    'au aux ce ces dans de des du en est et il la le les ou par pas pour que qui sur un une').split(' '));

  function fold(s) {            // same length as the input, so positions map back to the original text
    let out = '';
    for (let i = 0; i < s.length; i++) out += s[i].normalize('NFD')[0].toLowerCase()[0] || ' ';
    return out;
  }
  function esc(s) { return s.replace(/[&<>"]/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;' }[c])); }
  function build(allNodes) { nodes = allNodes; docs = null; }
  function prepare() {
    if (docs) return;
    const raw = (typeof window !== 'undefined' && window.TENIR_SEARCH_INDEX) || {};
    docs = {};
    nodes.forEach(n => {
      const body = raw[n.id] || '';
      const head = [n.label, (n.aliases || []).join(' '), (n.tags || []).join(' ')].join(' · ');
      docs[n.id] = { head:fold(head), excerpt:fold((n.properties && n.properties.excerpt) || ''), body, fbody:fold(body) };
    });
    lastInfo.indexed = Object.keys(raw).length;
  }
  function terms(query) {
    const all = fold(query || '').split(/[^a-z0-9À-￿+_-]+/).filter(t => t.length > 1);
    const kept = all.filter(t => !STOP.has(t));
    return (kept.length ? kept : all).map(t => (t.length > 4 && t.endsWith('s')) ? t.slice(0, -1) : t);
  }
  function rx(t) { return new RegExp('(^|[^a-z0-9])' + t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g'); }
  function count(re, s, cap) { let n = 0; re.lastIndex = 0; while (n < cap && re.exec(s)) n++; return n; }

  function snippet(d, res, n) {
    let src = d.body, f = d.fbody, pos = -1;
    for (const re of res) { re.lastIndex = 0; const m = re.exec(f); if (m && (pos < 0 || m.index < pos)) pos = m.index; }
    if (pos < 0) { src = (n.properties && n.properties.excerpt) || ''; f = d.excerpt; pos = 0; }
    if (!src) return '';
    const a = Math.max(0, pos - 90), b = Math.min(src.length, pos + 230);
    let html = esc(src.slice(a, b)), fpiece = fold(esc(src.slice(a, b)));
    const marks = [];
    res.forEach(re => { re.lastIndex = 0; let m; while ((m = re.exec(fpiece))) { const s = m.index + m[1].length; if (fpiece[s - 1] === '&') continue; let e = s; while (e < fpiece.length && /[a-z0-9À-￿_-]/.test(fpiece[e])) e++; marks.push([s, e]); } });
    marks.sort((p, q) => q[0] - p[0]);
    let last = Infinity;
    marks.forEach(([s, e]) => { if (e <= last) { html = html.slice(0, s) + '<mark>' + html.slice(s, e) + '</mark>' + html.slice(e); last = s; } });
    return (a > 0 ? '…' : '') + html + (b < src.length ? '…' : '');
  }

  function search(query) {
    prepare();
    const ts = terms(query); lastHits = {}; lastInfo = { terms:ts, partial:false, indexed:lastInfo.indexed };
    if (!ts.length) return [];
    const res = ts.map(rx), phrase = fold((query || '').trim());
    const scored = [];
    nodes.forEach(n => {
      const d = docs[n.id]; let score = 0, matched = 0;
      res.forEach(re => {
        const h = count(re, d.head, 3), x = count(re, d.excerpt, 3), b = count(re, d.fbody, 8);
        if (h || x || b) matched++;
        score += h * 8 + x * 3 + b;
      });
      if (!matched) return;
      if (ts.length > 1 && (d.head.includes(phrase) || d.fbody.includes(phrase))) score += 20;
      scored.push({ n, score, matched });
    });
    let hits = scored.filter(s => s.matched === ts.length);
    if (!hits.length) { hits = scored.filter(s => s.matched >= Math.max(1, ts.length - 1)); lastInfo.partial = hits.length > 0; }
    hits.sort((p, q) => q.matched - p.matched || q.score - p.score);
    hits = hits.slice(0, 60);
    hits.forEach(h => { lastHits[h.n.id] = { score:h.score, matched:h.matched, snippet:snippet(docs[h.n.id], res, h.n) }; });
    return hits.map(h => h.n);
  }
  // ---- passage level (used by Publish Projection) ----
  function sentences(id) {
    const d = docs[id]; if (!d || !d.body) return [];
    if (d.sents) return d.sents;
    const raw = d.body.split(/(?<=[.!?…:;])\s+(?=[A-ZÀ-Ý0-9"“«(#\[-])/), out = [];
    let buf = '';
    raw.forEach(p => {
      buf = buf ? buf + ' ' + p : p;
      if (buf.length < 70) return;
      let t = buf.replace(/[\u200b-\u200d\ufeff]/g, '').replace(/^[#>*\-\s|•·]+/, '').replace(/^(\d+\.)+\d*\s+(?=[A-ZÀ-Ý])/, '').replace(/\s+/g, ' ').trim(); buf = '';
      if (t.length > 460) { const cut = t.lastIndexOf(' ', 440); t = t.slice(0, cut > 200 ? cut : 440) + '…'; }
      const letters = (t.match(/[A-Za-zÀ-ÿ ]/g) || []).length;
      if (letters / t.length < 0.72 || (t.match(/\|/g) || []).length > 2 || /https?:\/\//.test(t)) return;
      out.push({ t, f:fold(t), q:quality(t) });
    });
    d.sents = out; return out;
  }
  function quality(t) {        // favours real sentences over headings, page furniture, tables and code
    let q = 0;
    if (/[.!?…»”"]$/.test(t)) q += 2;
    if (/^[A-ZÀ-Ý"“«]/.test(t)) q += 1;
    if (/Page \d+ (of|sur|\/) ?\d+/i.test(t)) q -= 9;
    if ((t.match(/\b[A-Z][A-Z0-9]*_[A-Z0-9_]+\b/g) || []).length >= 2) q -= 6;
    if (/\b\d+(\.\d+)+\s+[A-ZÀ-Ý]/.test(t)) q -= 5;
    if ((t.match(/[`{}<>=\\$]/g) || []).length >= 3) q -= 5;
    if ((t.match(/\d/g) || []).length / t.length > 0.08) q -= 3;
    const w = t.split(' '), head = w.slice(0, 5).join(' ');
    if (w.length > 12 && t.indexOf(head, head.length) > 0) q -= 9;
    if ((t.match(/ - | · | • | \| |→|✅|✔|☐/g) || []).length >= 3) q -= 7;
    if (/^(keywords|mots[- ]cl[ée]s|tags|jel)\b/i.test(t)) q -= 10;
    if (/\*\*|##|---|• •|`/.test(t)) q -= 6;
    if (/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/u.test(t)) q -= 4;
    const caps = w.filter(x => /^[A-ZÀ-Ý]/.test(x)).length;
    if (w.length > 8 && caps / w.length > 0.45) q -= 6;
    if (!/[a-zà-ÿ]{3,} [a-zà-ÿ]{2,} [a-zà-ÿ]{2,}/.test(t)) q -= 4;
    if (t.length > 110 && t.length < 340) q += 3;
    return q;
  }
  function need(n) { return n <= 3 ? n : Math.ceil(n * 0.6); }
  function hasTerms(res, f) { let m = 0; res.forEach(re => { re.lastIndex = 0; if (re.test(f)) m++; }); return m; }
  function dedupe(list, limit, skip) {
    const seen = new Set(skip || []), out = [], rest = [], perDoc = {};
    for (const p of list) {
      const k = fold(p.text).replace(/[^a-z0-9]/g, '').slice(0, 60); if (seen.has(k)) continue; seen.add(k);
      if (perDoc[p.id]) { rest.push(p); continue; } perDoc[p.id] = 1; out.push(p); if (out.length >= limit) break;
    }
    return out.concat(rest).slice(0, limit);
  }
  function passages(query, limit, skipKeys) {
    prepare();
    const ts = Array.isArray(query) ? query : terms(query); if (!ts.length) return [];
    const res = ts.map(rx), min = need(ts.length), out = [];
    const phrase = ts.length > 1 ? ts.join(' ') : null;
    nodes.forEach(n => {
      if (n.type !== 'artifact') return; const d = docs[n.id];
      if (!d.body || hasTerms(res, d.fbody) < min) return;
      const inTitle = hasTerms(res, d.head);
      sentences(n.id).forEach(s => {
        let m = 0, c = 0; res.forEach(re => { const k = count(re, s.f, 4); if (k) { m++; c += k; } });
        if (m < min) return;
        out.push({ id:n.id, text:s.t, score:m * 10 + Math.min(c, 6) + inTitle * 2 + s.q + (phrase && s.f.includes(phrase) ? 6 : 0) });
      });
    });
    out.sort((p, q) => q.score - p.score);
    return dedupe(out, limit || 5, skipKeys);
  }
  function bridges(qa, qb, limit) {
    prepare();
    const ta = (Array.isArray(qa) ? qa : terms(qa)), tb = (Array.isArray(qb) ? qb : terms(qb)).filter(t => !ta.includes(t));
    if (!ta.length || !tb.length) return [];
    const ra = ta.map(rx), rb = tb.map(rx), na = Math.ceil(ta.length / 2), nb = Math.ceil(tb.length / 2), out = [];
    nodes.forEach(n => {
      if (n.type !== 'artifact') return; const d = docs[n.id];
      if (!d.body || hasTerms(ra, d.fbody) < na || hasTerms(rb, d.fbody) < nb) return;
      const ss = sentences(n.id);
      ss.forEach((s, i) => {
        const a = hasTerms(ra, s.f), b = hasTerms(rb, s.f);
        if (a >= na && b >= nb) { out.push({ id:n.id, text:s.t, score:30 + (a + b) * 4 + s.q }); return; }
        const nx = ss[i + 1]; if (!nx || s.t.length + nx.t.length > 520) return;
        if ((a >= na && hasTerms(rb, nx.f) >= nb) || (b >= nb && hasTerms(ra, nx.f) >= na)) out.push({ id:n.id, text:s.t + ' ' + nx.t, score:14 + (a + b) * 4 + Math.min(s.q, nx.q) });
      });
    });
    out.sort((p, q) => q.score - p.score);
    return dedupe(out, limit || 3);
  }
  function sharedDocs(qa, qb) {
    prepare();
    const ra = (Array.isArray(qa) ? qa : terms(qa)).map(rx), rb = (Array.isArray(qb) ? qb : terms(qb)).map(rx);
    return nodes.filter(n => n.type === 'artifact' && docs[n.id].body && hasTerms(ra, docs[n.id].fbody) >= need(ra.length) && hasTerms(rb, docs[n.id].fbody) >= need(rb.length)).map(n => n.id);
  }
  return { build, search, hit: id => lastHits[id] || null, info: () => lastInfo, terms, passages, bridges, sharedDocs,
    key: t => fold(t).replace(/[^a-z0-9]/g, '').slice(0, 60) };
})();
